from dataclasses import dataclass

_NUM = r"(?:0|[1-9][0-9]*)"
_IDENT = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    rf"({_NUM})\\.({_NUM})\\.({_NUM})"
    rf"(?:-({_IDENT}(?:\\.{_IDENT})*))?"
    rf"(?:\\+({_IDENT}(?:\\.{_IDENT})*))?"
)
_COMPARATOR_RE = re.compile(r"(\\^|~|>=|<=|>|<|=)?(.*)", re.DOTALL)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION_RE.fullmatch(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, prerelease, build = match.groups()
    pre = tuple(prerelease.split(".")) if prerelease else ()
    for ident in pre:
        if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
            raise ValueError(f"invalid version: {text!r}")
    return Version(
        int(major),
        int(minor),
        int(patch),
        pre,
        tuple(build.split(".")) if build else (),
    )


def _coerce(version: str | Version) -> Version:
    return version if isinstance(version, Version) else parse(version)


def _compare_identifiers(a: str, b: str) -> int:
    a_num, b_num = a.isdigit(), b.isdigit()
    if a_num and b_num:
        x, y = int(a), int(b)
    elif a_num or b_num:
        return -1 if a_num else 1
    else:
        x, y = a, b
    return (x > y) - (x < y)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _coerce(a), _coerce(b)
    a_core = (a.major, a.minor, a.patch)
    b_core = (b.major, b.minor, b.patch)
    if a_core != b_core:
        return -1 if a_core < b_core else 1
    if not a.prerelease or not b.prerelease:
        # Without a pre-release is higher; both without are equal.
        return (not a.prerelease) - (not b.prerelease)
    for x, y in zip(a.prerelease, b.prerelease):
        result = _compare_identifiers(x, y)
        if result:
            return result
    la, lb = len(a.prerelease), len(b.prerelease)
    return (la > lb) - (la < lb)


