    """The comparator's version and the plain comparisons it stands for."""
    op, rest = _COMPARATOR_RE.fullmatch(text).groups()
    try:
        version = parse(rest)
    except ValueError:
        raise ValueError(f"invalid comparator: {text!r}") from None
    if op == "^":
        if version.major:
