from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = re.compile(r"(:?)-+(:?)")


def _cell_text(value) -> str:
    return "" if value is None else str(value).replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    space = width - len(text)
    if align == "right":
        return " " * space + text
    if align == "center":
        return " " * (space // 2) + text + " " * (space - space // 2)
    return text + " " * space


def _delimiter(width: int, align: str | None) -> str:
    left = ":" if align in ("left", "center") else "-"
    right = ":" if align in ("right", "center") else "-"
    return left + "-" * (width - 2) + right


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    if not header:
        raise ValueError("a table needs at least one column")
    columns = len(header)
    if align is None:
        align = [None] * columns
    if len(align) != columns:
        raise ValueError(f"expected {columns} alignments, got {len(align)}")
    for value in align:
        if value not in _ALIGNMENTS:
            raise ValueError(f"invalid alignment: {value!r}")

    header = [_cell_text(value) for value in header]
    texts = []
    for row in rows:
        if len(row) > columns:
            raise ValueError(f"row has {len(row)} cells, header has {columns}")
        texts.append(
            [_cell_text(value) for value in row] + [""] * (columns - len(row))
        )
    widths = [
        max([3, len(header[i])] + [len(row[i]) for row in texts])
        for i in range(columns)
    ]

    lines = [
        _line([_pad(c, w, a) for c, w, a in zip(header, widths, align)]),
        _line([_delimiter(w, a) for w, a in zip(widths, align)]),
    ]
    for row in texts:
        lines.append(_line([_pad(c, w, a) for c, w, a in zip(row, widths, align)]))
    return "\n".join(lines)


def _split_cells(line: str) -> list[str]:
    """Split a table line at unescaped pipes, dropping outer pipes."""
    line = line.strip()
    cells, current = [], []
    ends_with_pipe = False
    i = 0
    while i < len(line):
        char = line[i]
        if char == "\\" and line[i + 1:i + 2] == "|":
            current.append("|")
            i += 2
            ends_with_pipe = False
            continue
        if char == "|":
            cells.append("".join(current))
            current = []
            ends_with_pipe = True
        else:
            current.append(char)
            ends_with_pipe = False
        i += 1
    cells.append("".join(current))
    if line.startswith("|"):
        cells.pop(0)
    if ends_with_pipe and cells:
        cells.pop()
